// Production Design System — Android / Kotlin build (ADR 0013, 0017).
// :tokens is com.pds.tokens, generated by `npm run tokens:build`
// (packages/tokens/scripts/emit-kotlin.mjs) and committed. The Compose module (com.pds.compose)
// is reserved in compose/ and joins this build in Phase 5, together with the Android Gradle
// plugin, compileSdk / minSdk and the Compose versions.
pluginManagement {
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
}

dependencyResolutionManagement {
    repositories {
        mavenCentral()
    }
}

rootProject.name = "pds-android"

include(":tokens")
